// DEMO DATA - synthetic inventory snapshot. 12 stores + 1 warehouse, 20 SKUs, sizes 38-44.
// One item per (location, sku, size) with on_hand units and units sold in the last 30 days.
// Deterministic: a seeded generator, so every run returns the same snapshot.
function makeRng(seed) {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = makeRng(77031);
const pad = (n, w) => String(n).padStart(w, '0');
const cfg = $('Config').first().json;
const warehouse = String(cfg.warehouseName);
const heroList = String(cfg.heroSkus).split(',').map((s) => s.trim());

const stores = Array.from({ length: 12 }, (_, i) => 'Store A' + pad(i + 1, 2));
const skus = Array.from({ length: 20 }, (_, i) => 'SKU-' + (1001 + i));
const sizes = [38, 39, 40, 41, 42, 43, 44];
const curve = [0.5, 0.8, 1.2, 1.4, 1.2, 0.8, 0.5]; // mid sizes sell more
const storeScale = stores.map(() => 0.6 + rand() * 1.0);

const rows = [];
stores.forEach((store, si) => {
  skus.forEach((sku) => {
    const isHero = heroList.includes(sku);
    const skuBase = 2 + Math.floor(rand() * 5);
    sizes.forEach((size, zi) => {
      const sold = Math.floor(skuBase * curve[zi] * storeScale[si] * (isHero ? 2 : 1) * (0.5 + rand()));
      let onHand = Math.floor(sold * (0.5 + rand() * 3));
      if (isHero && rand() < 0.07 && sold > 0) onHand = 0; // hero stock-out with proven demand
      if (!isHero && rand() < 0.1) onHand = 0;
      rows.push({ json: { store: store, sku: sku, size: size, on_hand: onHand, sold_30d: sold } });
    });
  });
});
skus.forEach((sku) => {
  sizes.forEach((size, zi) => {
    const onHand = rand() < 0.35 ? 0 : Math.floor(curve[zi] * (4 + rand() * 20));
    rows.push({ json: { store: warehouse, sku: sku, size: size, on_hand: onHand, sold_30d: 0 } });
  });
});
return rows;

// Deterministic stock-out detection and transfer proposals. No LLM involved.
//
// Definitions
//   hero SKU      : a SKU listed in Config.heroSkus
//   gap           : hero SKU + size with on_hand = 0 at a store, and demand > 0
//   demand_30d    : units sold at that store in the last 30 days; if the store sold 0 (long stock-out),
//                   the average of stores that still have stock is used and demand_source says so
//   cover_days    : on_hand / (sold_30d / 30); a donor with no sales has unlimited cover
//   donor rules   : never drop a donor below donorMinKeep units; store donors need cover >= minDonorCoverDays
//   source order  : warehouse first when preferWarehouse is true, otherwise (or when the warehouse is
//                   empty) the store donor with the highest cover
//   ranking       : by demand_30d (units a gap loses per month), highest first
//   cap           : at most maxTransfers proposals per run
const cfg = $('Config').first().json;
const heroSkus = String(cfg.heroSkus).split(',').map((s) => s.trim()).filter(Boolean);
const warehouse = String(cfg.warehouseName);
const maxTransfers = Number(cfg.maxTransfers);
const targetUnits = Number(cfg.targetUnitsPerSize);
const donorMinKeep = Number(cfg.donorMinKeep);
const minCoverDays = Number(cfg.minDonorCoverDays);
const preferWarehouse = cfg.preferWarehouse === true;
const round1 = (n) => Math.round(n * 10) / 10;

const incoming = $input.all();
if (incoming.length > 0 && !incoming.some((i) => i.json.sku !== undefined && i.json.store !== undefined)) {
  // A disabled live node passes its input through unchanged, which would end up here.
  throw new Error('No inventory rows received. In live mode, enable the node "Sheets: Read Inventory (LIVE)".');
}
// Group by sku|size. Values may arrive as strings from a spreadsheet.
const cells = {};
for (const item of $input.all()) {
  const r = item.json;
  if (!heroSkus.includes(String(r.sku))) continue;
  const key = r.sku + '|' + Number(r.size);
  const c = cells[key] || (cells[key] = { sku: String(r.sku), size: Number(r.size), warehouse: 0, stores: [] });
  const onHand = Math.max(0, Number(r.on_hand) || 0);
  const sold = Math.max(0, Number(r.sold_30d) || 0);
  if (String(r.store) === warehouse) c.warehouse += onHand;
  else c.stores.push({ store: String(r.store), on_hand: onHand, sold_30d: sold });
}

if (Object.keys(cells).length === 0) {
  throw new Error('No inventory rows match the hero SKUs in Config.heroSkus. Check the SKU names.');
}

// 1. Find gaps
const gaps = [];
let heroCells = 0;
for (const c of Object.values(cells)) {
  heroCells += c.stores.length;
  const withStock = c.stores.filter((s) => s.on_hand > 0);
  const avgSold = withStock.length ? withStock.reduce((n, s) => n + s.sold_30d, 0) / withStock.length : 0;
  for (const s of c.stores) {
    if (s.on_hand !== 0) continue;
    const ownDemand = s.sold_30d > 0;
    const demand = ownDemand ? s.sold_30d : avgSold;
    if (demand <= 0) continue;
    gaps.push({ cell: c, store: s.store, demand_30d: round1(demand), demand_source: ownDemand ? 'store sales' : 'network average' });
  }
}
gaps.sort((a, b) => b.demand_30d - a.demand_30d || a.store.localeCompare(b.store) || a.cell.sku.localeCompare(b.cell.sku) || a.cell.size - b.cell.size);

// 2. Allocate sources, decrementing stock as we go so one unit is never promised twice
const proposals = [];
const unmatched = [];
const deferred = [];
const coverOf = (s) => (s.sold_30d > 0 ? s.on_hand / (s.sold_30d / 30) : Infinity);

for (const g of gaps) {
  const c = g.cell;
  let source = null;
  if (preferWarehouse && c.warehouse >= 1) {
    source = { type: 'warehouse', name: warehouse, qty: Math.min(targetUnits, c.warehouse), cover: null };
  }
  if (!source) {
    const donors = c.stores
      .filter((s) => s.store !== g.store && s.on_hand - donorMinKeep >= 1 && coverOf(s) >= minCoverDays)
      .sort((a, b) => coverOf(b) - coverOf(a) || b.on_hand - a.on_hand || a.store.localeCompare(b.store));
    if (donors.length) {
      const d = donors[0];
      source = { type: 'store', name: d.store, qty: Math.min(targetUnits, d.on_hand - donorMinKeep), cover: coverOf(d), donor: d };
    } else if (!preferWarehouse && c.warehouse >= 1) {
      source = { type: 'warehouse', name: warehouse, qty: Math.min(targetUnits, c.warehouse), cover: null };
    }
  }
  if (!source) {
    unmatched.push({ sku: c.sku, size: c.size, store: g.store, demand_30d: g.demand_30d, note: 'no stock available anywhere: reorder' });
    continue;
  }
  if (proposals.length >= maxTransfers) {
    deferred.push({ sku: c.sku, size: c.size, store: g.store, demand_30d: g.demand_30d });
    continue;
  }
  // reserve stock
  if (source.type === 'warehouse') c.warehouse -= source.qty;
  else source.donor.on_hand -= source.qty;
  proposals.push({
    rank: proposals.length + 1,
    sku: c.sku,
    size: c.size,
    to_store: g.store,
    from_location: source.name,
    from_type: source.type,
    qty: source.qty,
    demand_30d: g.demand_30d,
    demand_source: g.demand_source,
    donor_cover_days: source.cover === null || source.cover === Infinity ? null : round1(source.cover),
  });
}

// 3. Facts used for the summary (the LLM may only quote numbers from here)
const byStore = {};
for (const g of gaps) byStore[g.store] = (byStore[g.store] || 0) + 1;
const topStore = Object.entries(byStore).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0] || null;
const facts = {
  hero_skus: heroSkus.length,
  hero_size_cells_checked: heroCells,
  gaps_found: gaps.length,
  stores_with_gaps: Object.keys(byStore).length,
  transfers_proposed: proposals.length,
  from_warehouse: proposals.filter((p) => p.from_type === 'warehouse').length,
  from_stores: proposals.filter((p) => p.from_type === 'store').length,
  units_proposed: proposals.reduce((n, p) => n + p.qty, 0),
  deferred_by_cap: deferred.length,
  max_transfers_cap: maxTransfers,
  no_stock_anywhere: unmatched.length,
  top_proposal: proposals[0] || null,
  most_gaps_store: topStore ? { store: topStore[0], gaps: topStore[1] } : null,
};

return [
  {
    json: {
      kind: 'report',
      run_date: new Date().toISOString().slice(0, 10),
      facts: facts,
      proposals: proposals,
      unmatched: unmatched.slice(0, 20),
      deferred: deferred.slice(0, 20),
    },
  },
];

// Always builds the fallback summary first, then the (optional) LLM request.
const cfg = $('Config').first().json;
const report = $input.first().json;
const f = report.facts;

const lines = [];
lines.push(
  f.gaps_found + ' hero size gaps found in ' + f.stores_with_gaps + ' stores (' + f.hero_skus + ' hero SKUs, ' + f.hero_size_cells_checked + ' store-size cells checked).'
);
if (f.top_proposal) {
  const t = f.top_proposal;
  lines.push('Highest priority: ' + t.sku + ' size ' + t.size + ' at ' + t.to_store + ', demand ' + t.demand_30d + ' units in 30 days, proposed from ' + t.from_location + ' (' + t.qty + ' units).');
} else {
  lines.push('No transfer proposals this run.');
}
lines.push(f.transfers_proposed + ' transfers proposed (' + f.units_proposed + ' units): ' + f.from_warehouse + ' from the warehouse, ' + f.from_stores + ' from stores. ' + f.deferred_by_cap + ' more are deferred by the cap of ' + f.max_transfers_cap + '.');
lines.push(
  (f.most_gaps_store ? 'Most gaps: ' + f.most_gaps_store.store + ' (' + f.most_gaps_store.gaps + '). ' : '') + f.no_stock_anywhere + ' gaps have no stock anywhere and need a reorder.'
);
lines.push('No stock moves until a person approves the proposals.');
const templateSummary = lines.join('\n');

const system =
  'You write a 5-line operations summary for a retail inventory team.\n' +
  'Rules:\n' +
  '1. Use only the facts and numbers present in FACTS_JSON. Never calculate, estimate, round differently or invent a number, store, SKU or size.\n' +
  '2. If a value is null or missing, write n/a.\n' +
  '3. Output exactly 5 lines of plain text. No bullets, no markdown, no emoji.\n' +
  '4. Line 5 must say that no stock moves until a person approves the proposals.';

return [
  {
    json: {
      ...report,
      template_summary: templateSummary,
      llm_request: {
        model: String(cfg.llmModel),
        max_tokens: 400,
        system: system,
        messages: [{ role: 'user', content: 'FACTS_JSON:\n' + JSON.stringify(f) }],
      },
    },
  },
];

// Pick the LLM summary only if it passes the checks, otherwise use the template summary.
// Input is either the Anthropic response (LLM path) or the Build Summary Prompt item (no-LLM path).
const base = $('Build Summary Prompt').first().json;
const input = $input.first().json;
const llmText = input && Array.isArray(input.content) && input.content[0] ? String(input.content[0].text || '') : '';

function numbersIn(s) {
  return (String(s).match(/\d[\d,]*\.?\d*/g) || [])
    .map((t) => ({ val: Number(t.replace(/,/g, '').replace(/\.$/, '')), dec: ((t.split('.')[1] || '').match(/\d/g) || []).length }))
    .filter((x) => !Number.isNaN(x.val));
}
// Every number in the LLM text must match a number in the facts, within its own rounding.
function unknownNumbers(text, facts) {
  const known = numbersIn(JSON.stringify(facts)).map((x) => x.val);
  return numbersIn(text).filter((n) => !known.some((k) => Math.abs(k - n.val) <= 0.5 * Math.pow(10, -n.dec) + 1e-9));
}

let summary = base.template_summary;
let source = 'template';
let note = llmText ? '' : 'LLM not used or returned no text';
if (llmText) {
  const lines = llmText.split('\n').map((l) => l.trim()).filter(Boolean);
  const unknown = unknownNumbers(llmText, base.facts);
  if (lines.length !== 5) note = 'LLM output rejected: expected 5 lines, got ' + lines.length;
  else if (unknown.length) note = 'LLM output rejected: numbers not found in facts: ' + unknown.map((n) => n.val).join(', ');
  else {
    summary = lines.join('\n');
    source = 'llm';
    note = '';
  }
}
const out = { ...base, summary: summary, summary_source: source, summary_note: note };
delete out.llm_request;
delete out.template_summary;
return [{ json: out }];

// One row per proposal, flat columns for Google Sheets. Written BEFORE approval, status = proposed.
const r = $('Merge Summary').first().json;
return r.proposals.map((p) => ({
  json: {
    run_date: r.run_date,
    rank: p.rank,
    sku: p.sku,
    size: p.size,
    to_store: p.to_store,
    from_location: p.from_location,
    qty: p.qty,
    demand_30d: p.demand_30d,
    status: 'proposed',
  },
}));

// Runs only after a person chose "approve" in the approval form.
const r = $('Merge Summary').first().json;
const form = $input.first().json;
const approver = String(form.Approver || 'unknown');
const decidedAt = new Date().toISOString();
return r.proposals.map((p) => ({
  json: {
    run_date: r.run_date,
    rank: p.rank,
    sku: p.sku,
    size: p.size,
    to_store: p.to_store,
    from_location: p.from_location,
    qty: p.qty,
    status: 'approved',
    approved_by: approver,
    decided_at: decidedAt,
  },
}));

// Demo result: nothing is sent, written or approved. Shows what a person would be asked to approve.
const r = $input.first().json;
const table = r.proposals.map(
  (p) =>
    String(p.rank).padStart(2, ' ') + '. ' + p.sku + ' size ' + p.size + ' | ' + p.from_location + ' -> ' + p.to_store +
    ' | qty ' + p.qty + ' | demand ' + p.demand_30d + '/30d'
);
return [
  {
    json: {
      mode: 'demo',
      status: 'pending_approval',
      note: 'Demo run: nothing was sent, written or approved.',
      summary: r.summary,
      summary_source: r.summary_source,
      summary_note: r.summary_note,
      ranked_table: table.join('\n'),
      proposals: r.proposals,
      unmatched: r.unmatched,
      deferred: r.deferred,
      facts: r.facts,
    },
  },
];
